<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Core\database\DB;use Modules\Analytics\Services\AdminSettingService;use Modules\System\Services\AccessControl;use RuntimeException;
class AdminSettingController{public function __construct(private AdminSettingService$s,private AccessControl$access){}public function show(){return ResponseFactory::json(['success'=>true,'data'=>$this->s->get()]);}public function save(){try{$d=$this->payload();$actor=(int)auth()->id();$map=['primaryFont'=>'site_primary_font','fontScale'=>'site_font_size_scale','language'=>'site_language','themeMode'=>'site_theme_mode','colorTheme'=>'site_color_theme'];foreach($map as$field=>$key)if(array_key_exists($field,$d)){$setting=DB::table('z_settings')->where('`key`',$key)->whereNull('deleted_at')->first();$allowed=$setting?$this->access->settingAllows($actor,(int)$setting['setting_id']):$this->access->allows($actor,'settings.appearance.manage');if(!$allowed)throw new RuntimeException('مجوز تغییر این تنظیم را ندارید.');}return ResponseFactory::json(['success'=>true,'data'=>$this->s->save($actor,$d)]);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('تنظیمات معتبر نیست.');return$d;}}
